$p^jp_iM^{uiks}_j=0$. By a straightforward calculation,  we obtain
\begin{eqnarray}
p^jp_iM^{uiks}_j=p^jp_iC^{ks,i,u}_j\!\!\!\!&-&\!\!\!\!2c\beta\tau(G^{ks,u}+G^{kh}C^{us}_h+G^{uh}C^{ks}_h+G^{hs}C^{uk}_h)\nonumber\\
\!\!\!\!&+&\!\!\!\! 2c^2\beta^2\tau(G^{us}G^{kh}+G^{uk}G^{hs})p_h.\label{symmetric1}
\end{eqnarray}
By a direct computation, we have
\begin{equation}
G^{ks,u}=-2\beta
C^{ksu}+\frac{2c^2\beta^5}{(1-2c\beta^2\tau)^2}p^kp^up^s+\frac{c\beta^3}{1-2c\beta^2\tau}g^{ku}p^s+\frac{c\beta^3}{1-2c\beta^2\tau}g^{su}p^k.\label{symmetric2}
\end{equation}
Also, we obtain
\begin{equation}
G^{us}G^{kh}p_h=\frac{\beta}{1-2c\beta^2\tau}p^sG^{ku}=\frac{\beta^2}{1-2c\beta^2\tau}g^{ku}p^s+\frac{c\beta^4}{(1-2c\beta^2\tau)^2}p^up^kp^s,\label{symmetric3}
\end{equation}
and
\begin{equation}
G^{uk}G^{hs}p_h=\frac{\beta}{1-2c\beta^2\tau}p^kG^{su}=\frac{\beta^2}{1-2c\beta^2\tau}g^{su}p^k+\frac{c\beta^4}{(1-2c\beta^2\tau)^2}p^up^sp^k.\label{symmetric4}
\end{equation}
Putting (\ref{symmetric2}), (\ref{symmetric3}) and
(\ref{symmetric4}) in (\ref{symmetric1}), one can yields
\begin{equation}
p^jp_iM^{uiks}_j=p^jp_iC^{ks,i,u}_j-2c\beta\tau(-2\beta
C^{kus}+G^{kh}C^{us}_h+G^{uh}C^{ks}_h+G^{hs}C^{uk}_h).\label{symmetric5}
\end{equation}
Since $p_iC^{ks,i}_j=-C^{ks}_j$, then we obtain
\[
p^jp_iC^{ks,i,u}_j=2g^{uj}C^{ks}_j=2C^{kus}.
\]
Also, since
$C^{us}_hp^h=0$, then we have
\[
G^{kh}C^{us}_h=G^{uh}C^{ks}_h=G^{hs}C^{uk}_h=\beta C^{kus}.
\]
Therefore (\ref{symmetric5}) reduces to following
\begin{equation}
p^jp_iM^{uiks}_j=2(1-c\beta^2\tau)C^{kus}.\label{symmetric6}
\end{equation}
Since $p^jp_iM^{uiks}_j=0$, then by (\ref{symmetric6}), we have
$C^{kus}=0$, i.e., $K$  is a Riemannian metric.
\end{proof}
\begin{cor}
There is not exist any non-Riemannian Cartan structure such that
$(T^{\ast}M_0, G, J)$ became a locally symmetric manifold.
\end{cor}
